#!/usr/bin/env python3
"""Fit the polynomial pieces used by simd::erf/erfc/lgamma and emit math_coeffs.hpp.

Weighted least squares on Chebyshev nodes against CPython's libm (double), coefficients rounded
to float32 and re-checked with float32 Horner evaluation. Run: python ops/gen/fit_math.py > simd/include/forge/simd/math_coeffs.hpp
"""
import math, sys
import numpy as np
f32 = np.float32

def horner32(c, t):
    y = np.full_like(t, f32(c[0]))
    for a in c[1:]: y = (y * t + f32(a)).astype(f32)
    return y

def fit(fn, var, lo, hi, deg, n=4000):
    k = np.arange(n); x = 0.5 * (lo + hi) + 0.5 * (hi - lo) * np.cos(np.pi * (k + 0.5) / n)
    t = var(x); y = np.array([fn(v) for v in x]); w = 1 / np.abs(y)
    c, *_ = np.linalg.lstsq(np.vander(t, deg + 1) * w[:, None], y * w, rcond=None)
    c32 = c.astype(f32)
    err = np.max(np.abs(horner32(c32, var(x).astype(f32)).astype(np.float64) - y) / np.abs(y))
    return c32, err / 2**-24

out = ["#pragma once", "// Generated by ops/gen/fit_math.py - do not edit. Coefficients highest power first.", "namespace forge::simd::coeffs {"]
def emit(name, c, err, note):
    out.append(f"// {note}; fit error {err:.2f} ulp (float32 Horner)")
    out.append(f"inline constexpr float {name}[{len(c)}] = {{" + ", ".join(f"{float(v):.9e}f" for v in c) + "};")

c, e = fit(lambda x: math.erf(x) / x, lambda x: x * x, 1e-6, 1.0, 6); emit("erf_small", c, e, "erf(x)/x = P(x^2), x in [0,1]")
for i, (lo, hi, mid, deg) in enumerate([(0.5, 2, 1.25, 11), (2, 3.5, 2.75, 9), (3.5, 6, 4.75, 9), (6, 10.1, 8, 9)]):
    c, e = fit(lambda x: math.erfc(x) * math.exp(x * x), lambda x, m=mid: x - m, lo, hi, deg)
    emit(f"erfc_{i}", c, e, f"erfc(x)*exp(x^2) = P(x-{mid}), x in [{lo},{hi}]")
c, e = fit(lambda x: math.lgamma(x) / ((x - 1) * (x - 2)), lambda x: x - 2, 1.0, 3.0, 11); emit("lgamma_12", c, e, "lgamma(x)/((x-1)(x-2)) = P(x-2), x in [1,3]")
out.append("} // namespace forge::simd::coeffs")
print("\n".join(out))
